<?php require_once __DIR__.'/includes/functions.php';$token=$_GET['token']??'';$msg='Invalid or expired verification link.';$ok=false;
if(preg_match('/^[a-f0-9]{64}$/',$token)){$hash=hash('sha256',$token);$s=$conn->prepare("SELECT id,user_id FROM email_verifications WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()");$s->bind_param('s',$hash);$s->execute();$v=$s->get_result()->fetch_assoc();if($v){$conn->begin_transaction();try{$u=$conn->prepare("UPDATE users SET is_verified=1 WHERE id=?");$u->bind_param('i',$v['user_id']);$u->execute();$x=$conn->prepare("UPDATE email_verifications SET used_at=NOW() WHERE user_id=? AND used_at IS NULL");$x->bind_param('i',$v['user_id']);$x->execute();$conn->commit();$msg='Email verified. You may now log in.';$ok=true;}catch(Throwable $e){$conn->rollback();}}}
